{
  "root": "rootStack",
  "state": {
    "itinerary": [
      {
        "id": "day1",
        "day": "Day 1",
        "title": "The Northern Coast | San Francisco to Carmel-by-the-Sea",
        "driving": "~2 hours 30 minutes (125 miles)",
        "stop_title": "Pigeon Point Lighthouse",
        "stop_desc": "This historic 115-foot lighthouse offers a classic coastal California photo opportunity against the cliffs and ocean.",
        "hike_title": "Point Lobos State Natural Reserve",
        "hike_desc": "The Sea Lion Point Trail (0.6-mile loop) provides dramatic ocean views, access to tide pools, and abundant wildlife photography chances.",
        "stay_title": "Carmel-by-the-Sea",
        "stay_desc": "A charming town known for its European-style village, art galleries, and beautiful beach."
      },
      {
        "id": "day2",
        "day": "Day 2",
        "title": "The Heart of Big Sur | Carmel-by-the-Sea to Cambria",
        "driving": "~2 hours 30 minutes (90 miles)",
        "stop_title": "Bixby Creek Bridge",
        "stop_desc": "The most iconic landmark on Highway 1. Park in the designated pullouts on the north side of the bridge for the best and safest photographic angles.",
        "hike_title": "Partington Cove Trail",
        "hike_desc": "This 1-mile round-trip hike descends through a 60-foot tunnel to a secluded, rocky cove, offering a unique perspective of the Big Sur coast.",
        "stay_title": "Cambria",
        "stay_desc": "A quaint coastal village with a relaxed atmosphere, perfect for resting after a day of breathtaking views."
      },
      {
        "id": "day3",
        "day": "Day 3",
        "title": "The Central Coast Transition | Cambria to Santa Barbara",
        "driving": "~3 hours (130 miles)",
        "stop_title": "Elephant Seal Vista Point",
        "stop_desc": "Just north of San Simeon, this viewpoint offers incredible opportunities to photograph the massive northern elephant seals that haul out on the beach year-round.",
        "hike_title": "Fiscalini Ranch Preserve Bluff Trail",
        "hike_desc": "Before leaving Cambria, walk a portion of this easy 1-mile coastal trail for stunning views of the rocky shoreline and tide pools.",
        "stay_title": "Santa Barbara",
        "stay_desc": "Known as \"The American Riviera,\" this city features beautiful Spanish-style architecture, a palm-lined waterfront, and a mountainous backdrop."
      },
      {
        "id": "day4",
        "day": "Day 4",
        "title": "The Southern Approach | Santa Barbara to Los Angeles",
        "driving": "~2 hours (100 miles)",
        "stop_title": "Point Dume State Beach & Preserve",
        "stop_desc": "Located in Malibu, this promontory offers panoramic views of the coast, Zuma Beach, and Paradise Cove. It's a prime spot for sunset photography.",
        "hike_title": "Point Dume Nature Preserve Trail",
        "hike_desc": "A short, sandy loop trail (approx. 1 mile) takes you to the top of the bluff for the best vantage points.",
        "stay_title": "Los Angeles",
        "stay_desc": "Conclude your trip by arriving in the LA area, for example, near the iconic Santa Monica Pier."
      }
    ]
  },
  "elements": {
    "rootStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "title",
        "introText",
        "planningCard",
        "dailyGuideTitle",
        "itineraryStack",
        "quickActionsTitle",
        "roadConditionsButton",
        "imagesTitle",
        "imageGallery",
        "sourcesTitle",
        "sourcesStack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Pacific Coast Highway Photography Itinerary: SF to LA in 4 Days",
        "variant": "h2"
      },
      "children": []
    },
    "introText": {
      "type": "Text",
      "props": {
        "text": "This itinerary outlines a 4-day road trip from San Francisco to Los Angeles, focusing on photography and scenic coastal views. The plan is paced to keep daily driving under 4 hours, allowing ample time for exploration, hiking, and capturing the stunning California coastline.",
        "variant": "body"
      },
      "children": []
    },
    "planningCard": {
      "type": "Card",
      "props": {},
      "children": [
        "planningStack"
      ]
    },
    "planningStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "planningTitle",
        "planningText"
      ]
    },
    "planningTitle": {
      "type": "Text",
      "props": {
        "text": "Trip Planning Context",
        "variant": "h3"
      },
      "children": []
    },
    "planningText": {
      "type": "Text",
      "props": {
        "text": "This plan assumes you are traveling when Highway 1 is fully open. This route, particularly through Big Sur, is subject to periodic closures due to landslides. It is critical to check road conditions immediately before and during your trip. The driving times provided are estimates for active driving and do not include time for stops, meals, or potential traffic delays.",
        "variant": "body"
      },
      "children": []
    },
    "dailyGuideTitle": {
      "type": "Text",
      "props": {
        "text": "Daily Driving and Photography Guide",
        "variant": "h2"
      },
      "children": []
    },
    "itineraryStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "lg"
      },
      "children": [
        "dayCardTemplate"
      ],
      "repeat": {
        "statePath": "/itinerary",
        "key": "id"
      }
    },
    "dayCardTemplate": {
      "type": "Card",
      "props": {},
      "children": [
        "dayStack"
      ]
    },
    "dayStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "dayTitle",
        "drivingInfo",
        "stopInfo",
        "hikeInfo",
        "stayInfo"
      ]
    },
    "dayTitle": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "${/day}: ${/title}"
        },
        "variant": "h3"
      },
      "children": []
    },
    "drivingInfo": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "start"
      },
      "children": [
        "drivingIcon",
        "drivingTextStack"
      ]
    },
    "drivingIcon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000035_01_7_compass.svg"
      },
      "children": []
    },
    "drivingTextStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "drivingLabel",
        "drivingValue"
      ]
    },
    "drivingLabel": {
      "type": "Text",
      "props": {
        "text": "Driving Time",
        "variant": "label"
      },
      "children": []
    },
    "drivingValue": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "driving"
        },
        "variant": "body"
      },
      "children": []
    },
    "stopInfo": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "start"
      },
      "children": [
        "stopIcon",
        "stopTextStack"
      ]
    },
    "stopIcon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000002_01_1_camera.svg"
      },
      "children": []
    },
    "stopTextStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "stopLabel",
        "stopValue"
      ]
    },
    "stopLabel": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Major Scenic Stop: ${/stop_title}"
        },
        "variant": "label"
      },
      "children": []
    },
    "stopValue": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "stop_desc"
        },
        "variant": "body"
      },
      "children": []
    },
    "hikeInfo": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "start"
      },
      "children": [
        "hikeIcon",
        "hikeTextStack"
      ]
    },
    "hikeIcon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000036_01_2_house.svg"
      },
      "children": []
    },
    "hikeTextStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "hikeLabel",
        "hikeValue"
      ]
    },
    "hikeLabel": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Optional Short Hike: ${/hike_title}"
        },
        "variant": "label"
      },
      "children": []
    },
    "hikeValue": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "hike_desc"
        },
        "variant": "body"
      },
      "children": []
    },
    "stayInfo": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "align": "start"
      },
      "children": [
        "stayIcon",
        "stayTextStack"
      ]
    },
    "stayIcon": {
      "type": "Icon",
      "props": {
        "name": "../assets/r_000006_01_5_calendar-event.svg"
      },
      "children": []
    },
    "stayTextStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "none"
      },
      "children": [
        "stayLabel",
        "stayValue"
      ]
    },
    "stayLabel": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Overnight Stay: ${/stay_title}"
        },
        "variant": "label"
      },
      "children": []
    },
    "stayValue": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "stay_desc"
        },
        "variant": "body"
      },
      "children": []
    },
    "quickActionsTitle": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "roadConditionsButton": {
      "type": "Button",
      "props": {
        "label": "Check CA Highway 1 Road Conditions",
        "variant": "primary"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://roads.dot.ca.gov/"
          }
        }
      }
    },
    "imagesTitle": {
      "type": "Text",
      "props": {
        "text": "Images",
        "variant": "h2"
      },
      "children": []
    },
    "imageGallery": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "wrap": "wrap"
      },
      "children": [
        "image1",
        "image2",
        "image3",
        "image4"
      ]
    },
    "image1": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000036_01_4_bixby-bridge.jpg",
        "fit": "cover",
        "width": 150,
        "height": 100
      },
      "children": []
    },
    "image2": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000036_01_5_mcway-falls.jpg",
        "fit": "cover",
        "width": 150,
        "height": 100
      },
      "children": []
    },
    "image3": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000036_01_6_elephant-seal.jpg",
        "fit": "cover",
        "width": 150,
        "height": 100
      },
      "children": []
    },
    "image4": {
      "type": "Image",
      "props": {
        "url": "../assets/r_000036_01_7_malibu-coast.jpg",
        "fit": "cover",
        "width": 150,
        "height": 100
      },
      "children": []
    },
    "sourcesTitle": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "sourcesStack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "source1Button",
        "source2Button"
      ]
    },
    "source1Button": {
      "type": "Button",
      "props": {
        "label": "California Department of Parks and Recreation",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.parks.ca.gov/"
          }
        }
      }
    },
    "source2Button": {
      "type": "Button",
      "props": {
        "label": "Caltrans (California Department of Transportation)",
        "variant": "borderless"
      },
      "children": [],
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://dot.ca.gov/"
          }
        }
      }
    }
  }
}
